def longest_palindrome_subsequence(s: str) -> int:
    n = len(s)
    # 创建一个dp数组，用于存储子问题的结果
    dp = [[0] * n for _ in range(n)]

    # 初始化dp数组，每个字符都是长度为1的回文子序列
    for i in range(n):
        dp[i][i] = 1

    # 计算最长回文子序列长度
    for i in range(n):
        for j in range(i + 1, n):
        if s[i] == s[j]:
            if j == i + 1:
                dp[i][j] = dp[i+1][j-1] + 1
            else:
                dp[i][j] = max(dp[i][j], dp[i+1][j]) + 1
        else:
            dp[i][j] = max(dp[i][j], dp[i][j])

    # 返回最长回文子序列长度
    max_length = 0
    for i in range(n):
        for j in range(i, n):
            max_length = max(max_length, dp[i][j])

    return max_length

